<?php
require_once __DIR__ . '/../includes/db.php'; require_admin(); $page_title='Manage Bookings'; $bookings=$pdo->query('SELECT b.booking_id,b.start_date,b.end_date,b.total_amount,b.booking_status,i.item_name,r.name AS renter_name,o.name AS owner_name FROM bookings b INNER JOIN items i ON i.item_id=b.item_id INNER JOIN users r ON r.user_id=b.renter_id INNER JOIN users o ON o.user_id=b.owner_id ORDER BY b.created_at DESC')->fetchAll(); require_once __DIR__ . '/../includes/header.php'; require __DIR__ . '/_nav.php';
?>
<h1 class="h3 mb-4">Bookings</h1><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th class="ps-3">Item</th><th>Renter / Owner</th><th>Dates</th><th>Amount</th><th class="pe-3">Status</th></tr></thead><tbody><?php foreach($bookings as $booking): ?><tr><td class="ps-3"><?php echo e($booking['item_name']); ?></td><td><?php echo e($booking['renter_name']); ?><div class="small text-muted"><?php echo e($booking['owner_name']); ?></div></td><td><?php echo e($booking['start_date']); ?> to <?php echo e($booking['end_date']); ?></td><td><?php echo e(format_money($booking['total_amount'])); ?></td><td class="pe-3"><span class="badge text-bg-<?php echo e(status_badge_class($booking['booking_status'])); ?>"><?php echo e($booking['booking_status']); ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
